//! 🛬️ Explicit concrete Semio declaration owners and controlled native construction.
use semio_framework_test_fixtures::fixture_text;
use store::{bare_artifact_codec,os_store::serialization::ArtifactSqliteSnapshotHost,snapshot::ArtifactDsl,snapshot::ArtifactPack,os_store::serialization::ArtifactCodec};
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits,SnapshotEncoding};

fn check<P:ArtifactSqliteSnapshotHost+ArtifactDsl+ArtifactPack+Default+PartialEq+std::fmt::Debug+'static>(name:&str,subset:&str,codec:ArtifactCodec,failures:&mut Vec<String>){
    let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🪶️sqlite/🛬️native/🧫️fixtures/🔣️.json")).unwrap();assert!(fixture["owners"].as_array().unwrap().iter().any(|value|value.as_str()==Some(name)));
    let snapshot=P::default();
    let Some(provider)=codec.snapshot_sqlite.as_ref() else{failures.push(format!("{name}: declaration has no capability"));return};
    if provider.snapshot_type!=Some(std::any::TypeId::of::<P>()){failures.push(format!("{name}: declaration type differs"));return;}
    let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:subset.into()};
    for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(snapshot.encode_pack()),SnapshotEncoding::Text=>store::io::IoPayload::Text(snapshot.print_dsl())};
        match semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| P::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)){Ok(actual)=>assert_eq!(actual,snapshot,"{name} {encoding:?}"),Err(error)=>{failures.push(format!("{name} {encoding:?}: {error}"));continue;}}
        if let Err(error)=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| (provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)){failures.push(format!("{name} declaration {encoding:?}: {error:?}"));}
    }
}

#[test]
fn sqlite_snapshot_000_semio_every_concrete_bare_declaration_owner_has_controlled_native_construction(){
    crate::declaration(crate::definition().unwrap(), &[]).unwrap();
    let mut failures=Vec::new();
    check::<crate::schema::snapshot::SemioSnapshot>("base","*",bare_artifact_codec::<crate::schema::snapshot::SemioSnapshot,crate::schema::mutations::SemioMutation>(<crate::schema::snapshot::SemioSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_text_model::schema::snapshot::SemioTextSnapshot>("text","text",bare_artifact_codec::<semio_s_artifact_stdio_semio_text_model::schema::snapshot::SemioTextSnapshot,semio_s_artifact_stdio_semio_text_mutations::schema::mutations::SemioTextMutation>(<semio_s_artifact_stdio_semio_text_model::schema::snapshot::SemioTextSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_value_model::schema::snapshot::SemioValueSnapshot>("value","value",bare_artifact_codec::<semio_s_artifact_stdio_semio_value_model::schema::snapshot::SemioValueSnapshot,semio_s_artifact_stdio_semio_value_mutations::schema::mutations::SemioValueMutation>(<semio_s_artifact_stdio_semio_value_model::schema::snapshot::SemioValueSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_audio_model::schema::snapshot::SemioAudioSnapshot>("audio","audio",bare_artifact_codec::<semio_s_artifact_stdio_semio_audio_model::schema::snapshot::SemioAudioSnapshot,semio_s_artifact_stdio_semio_audio_mutations::schema::mutations::SemioAudioMutation>(<semio_s_artifact_stdio_semio_audio_model::schema::snapshot::SemioAudioSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_video_model::schema::snapshot::SemioVideoSnapshot>("video","video",bare_artifact_codec::<semio_s_artifact_stdio_semio_video_model::schema::snapshot::SemioVideoSnapshot,semio_s_artifact_stdio_semio_video_mutations::schema::mutations::SemioVideoMutation>(<semio_s_artifact_stdio_semio_video_model::schema::snapshot::SemioVideoSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_image::schema::snapshot::SemioImageSnapshot>("image","image",bare_artifact_codec::<semio_s_artifact_stdio_semio_image::schema::snapshot::SemioImageSnapshot,semio_s_artifact_stdio_semio_image::schema::mutations::SemioImageMutation>(<semio_s_artifact_stdio_semio_image::schema::snapshot::SemioImageSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_flow::schema::snapshot::SemioFlowSnapshot>("flow","flow",bare_artifact_codec::<semio_s_artifact_stdio_semio_flow::schema::snapshot::SemioFlowSnapshot,semio_s_artifact_stdio_semio_flow::schema::mutations::SemioFlowMutation>(<semio_s_artifact_stdio_semio_flow::schema::snapshot::SemioFlowSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_table_model::schema::snapshot::SemioTableSnapshot>("table","table",bare_artifact_codec::<semio_s_artifact_stdio_semio_table_model::schema::snapshot::SemioTableSnapshot,semio_s_artifact_stdio_semio_table_mutations::schema::mutations::SemioTableMutation>(<semio_s_artifact_stdio_semio_table_model::schema::snapshot::SemioTableSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_graph::schema::snapshot::SemioGraphSnapshot>("graph","graph",bare_artifact_codec::<semio_s_artifact_stdio_semio_graph::schema::snapshot::SemioGraphSnapshot,semio_s_artifact_stdio_semio_graph::schema::mutations::SemioGraphMutation>(<semio_s_artifact_stdio_semio_graph::schema::snapshot::SemioGraphSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_animation::schema::snapshot::SemioAnimationSnapshot>("animation","animation",bare_artifact_codec::<semio_s_artifact_stdio_semio_animation::schema::snapshot::SemioAnimationSnapshot,semio_s_artifact_stdio_semio_animation::schema::mutations::SemioAnimationMutation>(<semio_s_artifact_stdio_semio_animation::schema::snapshot::SemioAnimationSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_object::schema::snapshot::SemioObjectSnapshot>("object","object",bare_artifact_codec::<semio_s_artifact_stdio_semio_object::schema::snapshot::SemioObjectSnapshot,semio_s_artifact_stdio_semio_object::schema::mutations::SemioObjectMutation>(<semio_s_artifact_stdio_semio_object::schema::snapshot::SemioObjectSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_kit::schema::snapshot::SemioKitSnapshot>("kit","kit",bare_artifact_codec::<semio_s_artifact_stdio_semio_kit::schema::snapshot::SemioKitSnapshot,semio_s_artifact_stdio_semio_kit::schema::mutations::SemioKitMutation>(<semio_s_artifact_stdio_semio_kit::schema::snapshot::SemioKitSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_mesh::schema::snapshot::SemioMeshSnapshot>("mesh","mesh",bare_artifact_codec::<semio_s_artifact_stdio_semio_mesh::schema::snapshot::SemioMeshSnapshot,semio_s_artifact_stdio_semio_mesh::schema::mutations::SemioMeshMutation>(<semio_s_artifact_stdio_semio_mesh::schema::snapshot::SemioMeshSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_model::schema::snapshot::SemioModelSnapshot>("model","model",bare_artifact_codec::<semio_s_artifact_stdio_semio_model::schema::snapshot::SemioModelSnapshot,semio_s_artifact_stdio_semio_model::schema::mutations::SemioModelMutation>(<semio_s_artifact_stdio_semio_model::schema::snapshot::SemioModelSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_cad::schema::snapshot::SemioCadSnapshot>("cad","cad",bare_artifact_codec::<semio_s_artifact_stdio_semio_cad::schema::snapshot::SemioCadSnapshot,semio_s_artifact_stdio_semio_cad::schema::mutations::SemioCadMutation>(<semio_s_artifact_stdio_semio_cad::schema::snapshot::SemioCadSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_document::schema::snapshot::SemioDocumentSnapshot>("document","document",bare_artifact_codec::<semio_s_artifact_stdio_semio_document::schema::snapshot::SemioDocumentSnapshot,semio_s_artifact_stdio_semio_document::schema::mutations::SemioDocumentMutation>(<semio_s_artifact_stdio_semio_document::schema::snapshot::SemioDocumentSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_drawing::schema::snapshot::SemioDrawingSnapshot>("drawing","drawing",bare_artifact_codec::<semio_s_artifact_stdio_semio_drawing::schema::snapshot::SemioDrawingSnapshot,semio_s_artifact_stdio_semio_drawing::schema::mutations::SemioDrawingMutation>(<semio_s_artifact_stdio_semio_drawing::schema::snapshot::SemioDrawingSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_presentation::schema::snapshot::SemioPresentationSnapshot>("presentation","presentation",bare_artifact_codec::<semio_s_artifact_stdio_semio_presentation::schema::snapshot::SemioPresentationSnapshot,semio_s_artifact_stdio_semio_presentation::schema::mutations::SemioPresentationMutation>(<semio_s_artifact_stdio_semio_presentation::schema::snapshot::SemioPresentationSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    check::<semio_s_artifact_stdio_semio_brep::schema::snapshot::SemioBrepSnapshot>("brep","brep",bare_artifact_codec::<semio_s_artifact_stdio_semio_brep::schema::snapshot::SemioBrepSnapshot,semio_s_artifact_stdio_semio_brep::schema::mutations::SemioBrepMutation>(<semio_s_artifact_stdio_semio_brep::schema::snapshot::SemioBrepSnapshot as ArtifactDsl>::envelope_id()),&mut failures);
    assert!(failures.is_empty(),"{}",failures.join("\n"));
}
